// =============================
// DETECTA FINALIZAÇÃO — v4
// Agora detecta envio completo e confirmação de pagamento
// =============================

// 1) Pega mensagem consolidada se existir
let mensagem = $json.mensagemCliente;

// 2) Se não existir, tenta pegar do webhook (texto curto)
if (!mensagem || mensagem.trim() === "") {
  const raw = $json.body?.data?.message;

  mensagem =
    raw?.extendedTextMessage?.text ||
    raw?.conversation ||
    null;
}

// 3) Como último fallback, usa Redis2 (última mensagem)
if (!mensagem || mensagem.trim() === "") {
  const r2 = $json.Redis2;
  if (typeof r2 === "string" && r2.trim() !== "") {
    mensagem = r2;
  }
}

// 4) Se mesmo assim nada, define como vazio
mensagem = (mensagem || "").trim().toLowerCase();

// ===============
// Gatilhos de finalização de envio
// ===============
const gatilhosEnvio = [
  "pronto",
  "acabei",
  "finalizei",
  "terminei",
  "enviei tudo",
  "acho que terminei",
  "prontinho",
  "acho que foi tudo",
  "pode olhar",
  "acho que acabou",
  "concluí"
];

// ===============
// Gatilhos de pagamento confirmado
// ===============
const gatilhosPagamento = [
  "paguei",
  "efetuei o pagamento",
  "já paguei",
  "comprovante",
  "pix enviado",
  "enviei o comprovante",
  "pix feito",
  "acabei de pagar"
];

// Lista de negações (pra evitar falso positivo)
const negacoes = [
  "ainda",
  "mais",
  "vou mandar",
  "enviar mais",
  "enviando",
  "falta",
  "continuar",
  "vou pagar",
  "vou fazer o pix",
  "ainda não paguei"
];

// Função pra checar se contém negação
function contemNegacao(t) {
  return negacoes.some(n => t.includes(n));
}

// Verifica se é gatilho de envio ou pagamento
const ehEnvio = gatilhosEnvio.some(g => mensagem === g || mensagem.includes(g));
const ehPagamento = gatilhosPagamento.some(g => mensagem.includes(g));

// =============================
// OUTPUT FINAL DO NODE
// =============================

if ((ehEnvio || ehPagamento) && !contemNegacao(mensagem)) {
  return [
    {
      json: {
        finalizar: true,
        tipo: ehPagamento ? "pagamento" : "envio",
        motivo: ehPagamento
          ? "Gatilho de confirmação de pagamento detectado"
          : "Gatilho de finalização de envio detectado",
        mensagemCliente: mensagem
      }
    }
  ];
}

return [
  {
    json: {
      finalizar: false,
      motivo: "Mensagem comum",
      mensagemCliente: mensagem
    }
  }
];

// Garante que temos arrays válidos vindos dos Redis
const redis1 = $json.redis1 || [];
const redis2 = $json.redis2 || [];

// Junta tudo em um array só
const allUrls = [...redis1, ...redis2];

// Mapeia cada url para o formato exigido pelo Airtable
const airtableAttachments = allUrls.map(url => ({ url }));

return [
  {
    json: {
      'Arquivos e mídia': airtableAttachments
    }
  }
];

// Pega os dados dos dois nodes de entrada
const redis1 = $items('memoria_redis3')[0].json.redis1 || [];
const redis2 = $items('Redis7')[0].json.redis2 || [];

// Junta as listas
const allUrls = [...redis1, ...redis2];

// Transforma as URLs no formato que o Airtable espera
const airtableAttachments = allUrls.map(url => ({ url }));

return [
  {
    json: {
      'Arquivos e mídia': airtableAttachments,
    }
  }
];

const arr1 = $json.redis1 || [];
const arr2 = $json.redis2 || [];

const sameValues = arr1.length === arr2.length &&
  arr1.every(item => arr2.includes(item));

return [{ json: { mesmaLista: sameValues } }];

const lead = $json.lead || $json;
const deal = $json.deal || {};
const conversation = $json.conversation || {};
const recentMessages = $json.recent_messages || [];
const meta = lead.metadata || {};

function text(value) {
  if (!value) return '';
  if (Array.isArray(value)) return value.join(', ');
  return String(value);
}

let ctx = $json._context || '';

if (!ctx) {
  ctx = `<estado_atual>
STATUS: ${lead.status || 'new'}
Cliente: ${lead.name || 'Lead'}
Telefone: ${lead.phone || ''}
lead_id: ${lead.id || ''}
deal_id: ${deal.id || ''}
conversation_id: ${conversation.id || ''}
ai_paused: ${conversation.ai_paused === true ? 'true' : 'false'}
</estado_atual>`;
}

return [{
  json: {
    ...$json,
    ...lead,
    lead,
    deal,
    conversation,
    recent_messages: recentMessages,
    _context: ctx,
    _status_slug: lead.status || 'new',
    nome_cliente: lead.name || 'Lead',
    record_id_guardiao: lead.id || '',
    Telefone: lead.phone,
    'Status Lead': lead.status,
    'Score do Lead': lead.score,
    mensagemCliente: $json.mensagemCliente || $json.mensagem || ''
  }
}];

const items = $input.all();
const output = [];

for (const item of items) {

const body = item.json.body || {};
const data = body.data || {};
const headers = item.json.headers || {};
const query = item.json.query || {};


// ===============================
// IGNORAR MENSAGENS DO BOT
// ===============================

if (data?.key?.fromMe === true) {
continue;
}


// ===============================
// TELEFONE / JID
// ===============================

let remoteJid = data?.key?.remoteJid || "";
let remoteJidAlt = data?.key?.remoteJidAlt || "";

let jid = null;

if (remoteJid.includes("@s.whatsapp.net")) {
jid = remoteJid;
}
else if (remoteJidAlt.includes("@s.whatsapp.net")) {
jid = remoteJidAlt;
}

let telefoneCompleto = null;
let telefoneDDI = null;
let telefoneLocal = null;
let sessionId = null;

if (jid) {

telefoneCompleto = jid.split("@")[0];

telefoneDDI = telefoneCompleto.substring(0,2);
const ddd = telefoneCompleto.substring(2,4);
let numero = telefoneCompleto.substring(4);

// correção automática Brasil
if (telefoneDDI === "55" && numero.length === 8) {
numero = "9" + numero;
}

telefoneLocal = ddd + numero;
telefoneCompleto = telefoneDDI + telefoneLocal;

sessionId = telefoneCompleto;

}


// ===============================
// NOME
// ===============================

const nome = data.pushName || "Cliente";


// ===============================
// MESSAGE TYPE
// ===============================

let messageType = "unknown";
let mensagem = null;

let audioUrl = null;
let audioSegundos = null;


// TEXTO SIMPLES
if (data.message?.conversation) {

messageType = "text";
mensagem = data.message.conversation;

}

// TEXTO EXTENDIDO
else if (data.message?.extendedTextMessage?.text) {

messageType = "text";
mensagem = data.message.extendedTextMessage.text;

}

// AUDIO
else if (data.message?.audioMessage) {

messageType = "audio";

audioUrl = data.message.audioMessage.url || null;
audioSegundos = data.message.audioMessage.seconds || null;

mensagem = "[audio]";

}

// IMAGEM
else if (data.message?.imageMessage) {

messageType = "image";
mensagem = "[image]";

}

// DOCUMENTO
else if (data.message?.documentMessage) {

messageType = "document";
mensagem = "[document]";

}


// ===============================
// TIMESTAMP
// ===============================

const timestamp = data.messageTimestamp || null;

let dataMensagem = null;

if (timestamp) {
dataMensagem = new Date(timestamp * 1000).toISOString();
}


// ===============================
// DETECTAR ORIGEM DO LEAD
// ===============================

let origemLead = "WhatsApp Site";

const utmSource = (query.utm_source || "").toLowerCase();

if (utmSource.includes("google")) {
origemLead = "Google Ads";
}

else if (
utmSource.includes("facebook") ||
utmSource.includes("meta")
) {
origemLead = "Meta Ads";
}

else if (utmSource.includes("instagram")) {
origemLead = "Instagram Orgânico";
}

else if (
utmSource.includes("zap") ||
utmSource.includes("vivareal") ||
utmSource.includes("olx")
) {
origemLead = "Portal Imobiliário";
}

else if (utmSource.includes("jp")) {
origemLead = "Anúncio JP";
}


// ===============================
// OUTPUT FINAL
// ===============================

output.push({

json: {

eventType: "WHATSAPP_MESSAGE",

instance: body.instance || null,

nome,

remoteJid: jid,

telefoneCompleto,
telefoneDDI,
telefoneLocal,

sessionId,

messageType,

mensagem,

audioUrl,
audioSegundos,

timestamp,
dataMensagem,

origemLead,

source: data.source || "whatsapp"

}

});

}

return output;

function normalizePhone(input) {
  if (input === null || input === undefined) return '';
  return String(input).replace(/\D/g, '').trim();
}

function text(value) {
  if (!value) return '';
  if (Array.isArray(value)) return value.join(', ');
  return String(value);
}

async function n8nHttpRequest(options) {
  if (this && this.helpers && typeof this.helpers.httpRequest === 'function') {
    return await this.helpers.httpRequest(options);
  }
  if (this && this.helpers && typeof this.helpers.request === 'function') {
    return await this.helpers.request(options);
  }
  throw new Error('Nenhum helper HTTP disponível no Code node.');
}

async function supabaseRequest({ baseUrl, apiKey, method, path, qs = {}, body, prefer }) {
  const cleanBase = String(baseUrl).replace(/\/+$/, '');
  const cleanPath = String(path).startsWith('/') ? path : `/${path}`;
  const headers = {
    apikey: apiKey,
    Authorization: `Bearer ${apiKey}`,
    'Content-Type': 'application/json',
  };
  if (prefer) headers.Prefer = prefer;

  const options = {
    method,
    url: `${cleanBase}${cleanPath}`,
    qs,
    headers,
    json: true,
  };
  if (body !== undefined) options.body = body;

  try {
    return await n8nHttpRequest.call(this, options);
  } catch (error) {
    const responseBody =
      error?.response?.data ||
      error?.response?.body ||
      error?.context ||
      error?.description ||
      error?.message ||
      error;

    throw new Error(
      `Supabase ${method} ${path} falhou. BODY: ${JSON.stringify(body)} DETALHE: ${JSON.stringify(responseBody)}`
    );
  }
}

function isPlainObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value);
}

function mergeMetadata(base, extra) {
  return { ...(isPlainObject(base) ? base : {}), ...(isPlainObject(extra) ? extra : {}) };
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const text = String(value ?? '').trim();
    if (text) return text;
  }
  return null;
}

function normalizeForInference(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function parseOperationalMoney(value) {
  const raw = String(value ?? '').trim();
  if (!raw) return null;
  const compact = raw
    .replace(/r\$/gi, '')
    .replace(/\s/g, '')
    .replace(/\./g, '')
    .replace(',', '.');
  const number = Number(compact);
  if (!Number.isFinite(number)) return null;
  if (/\b(milhao|milhoes|mi)\b/i.test(raw)) return Math.round(number * 1000000);
  if (/\b(k|mil)\b/i.test(raw) && number < 10000) return Math.round(number * 1000);
  return Math.round(number);
}

function inferOperationalExtraction({ lead, deal, mensagem, origemLead }) {
  const meta = mergeMetadata(lead?.metadata, deal?.metadata);
  const text = normalizeForInference([
    mensagem,
    meta.primeira_mensagem,
    meta.bairro_interesse,
    meta.tipo_imovel,
    meta.finalidade,
    meta.objetivo,
    deal?.location_preference,
    deal?.property_type,
    deal?.intent,
    deal?.purpose,
    origemLead,
  ].filter(Boolean).join(' '));

  const neighborhoods = [
    ['ponta de campina', 'Ponta de Campina'],
    ['jardim oceania', 'Jardim Oceania'],
    ['cabo branco', 'Cabo Branco'],
    ['intermares', 'Intermares'],
    ['manaira', 'Manaira'],
    ['tambau', 'Tambau'],
    ['bessa', 'Bessa'],
    ['camboinha', 'Camboinha'],
    ['altiplano', 'Altiplano'],
    ['aeroclube', 'Aeroclube'],
  ];

  const location = firstNonEmpty(
    deal?.location_preference,
    meta.bairro_interesse,
    meta.bairro,
    neighborhoods.find(([needle]) => text.includes(needle))?.[1],
  );

  const propertyType = firstNonEmpty(
    deal?.property_type,
    meta.tipo_imovel,
    text.includes('cobertura') ? 'cobertura' : null,
    text.includes('apartamento') || text.includes('apto') ? 'apartamento' : null,
    text.includes('casa') ? 'casa' : null,
    text.includes('flat') || text.includes('studio') ? 'flat' : null,
    text.includes('terreno') ? 'terreno' : null,
  );

  const intent = firstNonEmpty(
    deal?.intent,
    meta.objetivo,
    text.includes('invest') || text.includes('rentabilidade') || text.includes('valorizacao') ? 'investir' : null,
    text.includes('alugar') || text.includes('locacao') ? 'alugar' : null,
    text.includes('comprar') || text.includes('morar') ? 'comprar' : null,
  );

  const bedroomsMatch = text.match(/\b([1-6])\s*(?:quartos?|qts?|dormitorios?|dorms?)\b/);
  const budgetMatch =
    text.match(/(?:ate|maximo|max|teto|orcamento(?: de)?|valor(?: de)?|faixa(?: de)?)\s*(?:r\$)?\s*([0-9]+(?:[.,][0-9]+)?\s*(?:milhao|milhoes|mi|mil|k)?)/) ||
    text.match(/(?:r\$)\s*([0-9]+(?:[.,][0-9]+)?\s*(?:milhao|milhoes|mi|mil|k)?)/);
  const timelineMatch = text.match(/\b(?:ate\s*)?([0-9]{1,2})\s*(dias|meses|mes)\b/);

  return {
    intent,
    bedrooms: firstNonEmpty(deal?.bedrooms, meta.quartos, bedroomsMatch?.[1]),
    location,
    timeline: firstNonEmpty(deal?.timeline, meta.timeline, meta.prazo, timelineMatch ? timelineMatch[0] : null),
    budget_max: deal?.budget_max ?? parseOperationalMoney(meta.faixa_valor ?? meta.valor_max ?? budgetMatch?.[1]),
    motivation: firstNonEmpty(
      deal?.motivation,
      meta.motivation,
      text.includes('familia') || text.includes('filho') || text.includes('escola') ? 'familia_rotina' : null,
      text.includes('praia') || text.includes('mar') ? 'lifestyle_praia' : null,
      text.includes('invest') || text.includes('retorno') ? 'investimento' : null,
    ),
    property_type: propertyType,
    decision_maker: firstNonEmpty(
      deal?.decision_maker,
      meta.decision_maker,
      text.includes('casal') || text.includes('esposa') || text.includes('marido') ? 'casal' : null,
      text.includes('familia') ? 'familia' : null,
    ),
    payment_method: firstNonEmpty(
      deal?.payment_method,
      meta.payment_method,
      meta.pagamento,
      text.includes('financiamento') ? 'financiamento' : null,
      text.includes('fgts') ? 'fgts' : null,
      text.includes('a vista') || text.includes('à vista') ? 'a_vista' : null,
    ),
  };
}

function mergeExtractedState(existing, inferred) {
  const base = isPlainObject(existing) ? existing : {};
  const merged = { ...base };
  for (const [key, value] of Object.entries(inferred || {})) {
    if (value !== null && value !== undefined && String(value).trim() !== '') {
      merged[key] = value;
    } else if (!(key in merged)) {
      merged[key] = null;
    }
  }
  return merged;
}

function buildOperationalDealMetadata({ lead, deal, mensagem, origemLead, now }) {
  const current = isPlainObject(deal?.metadata) ? deal.metadata : {};
  const lastExtracted = mergeExtractedState(
    current.last_extracted,
    inferOperationalExtraction({ lead, deal, mensagem, origemLead }),
  );
  const missingFields = ['intent', 'location', 'budget_max', 'timeline', 'property_type']
    .filter((key) => !firstNonEmpty(lastExtracted[key]));

  return mergeMetadata(current, {
    entrypoint: firstNonEmpty(current.entrypoint, 'evolution'),
    lead_source_context: firstNonEmpty(current.lead_source_context, normalizeForInference(origemLead).includes('whatsapp') ? 'whatsapp' : origemLead, 'whatsapp'),
    last_extracted: lastExtracted,
    missing_fields: missingFields,
    profile_complete: missingFields.length === 0,
    last_state_sync_at: now,
  });
}

function buildOperationalDealPatch({ lead, deal, mensagem, origemLead, telefone, nome, now }) {
  const metadata = buildOperationalDealMetadata({ lead, deal, mensagem, origemLead, now });
  const extracted = metadata.last_extracted || {};
  const patch = {
    client_name: deal?.client_name || lead?.name || nome || null,
    client_phone: deal?.client_phone || telefone || null,
    metadata,
    updated_at: now,
  };

  if (!deal?.intent && firstNonEmpty(extracted.intent)) patch.intent = extracted.intent;
  if (!deal?.location_preference && firstNonEmpty(extracted.location)) patch.location_preference = extracted.location;
  if (!deal?.budget_max && extracted.budget_max) patch.budget_max = extracted.budget_max;
  if (!deal?.bedrooms && firstNonEmpty(extracted.bedrooms)) patch.bedrooms = String(extracted.bedrooms);
  if (!deal?.property_type && firstNonEmpty(extracted.property_type)) patch.property_type = extracted.property_type;
  if (!deal?.timeline && firstNonEmpty(extracted.timeline)) patch.timeline = extracted.timeline;
  if (!deal?.payment_method && firstNonEmpty(extracted.payment_method)) patch.payment_method = extracted.payment_method;
  if (!deal?.motivation && firstNonEmpty(extracted.motivation)) patch.motivation = extracted.motivation;
  if (!deal?.decision_maker && firstNonEmpty(extracted.decision_maker)) patch.decision_maker = extracted.decision_maker;
  if (!deal?.qualification_status) patch.qualification_status = metadata.profile_complete ? 'morno' : 'incompleto';
  if (!deal?.deal_stage) patch.deal_stage = 'qualificacao';

  Object.keys(patch).forEach((key) => {
    if (patch[key] === null || patch[key] === undefined || patch[key] === '') delete patch[key];
  });

  return patch;
}

function validHttpUrl(value) {
  const raw = String(value ?? '').trim();
  if (!/^https?:\/\//i.test(raw)) return '';
  if (/\s|localhost|127\.0\.0\.1/i.test(raw)) return '';
  return raw;
}

function pickProfilePictureUrl(payload) {
  if (!payload) return '';
  if (typeof payload === 'string') return validHttpUrl(payload);
  if (Array.isArray(payload)) {
    for (const item of payload) {
      const url = pickProfilePictureUrl(item);
      if (url) return url;
    }
    return '';
  }
  if (typeof payload !== 'object') return '';

  const candidates = [
    payload.profilePictureUrl,
    payload.profilePicture,
    payload.pictureUrl,
    payload.picture,
    payload.url,
    payload.data?.profilePictureUrl,
    payload.data?.profilePicture,
    payload.data?.pictureUrl,
    payload.data?.picture,
    payload.data?.url,
  ];

  for (const candidate of candidates) {
    const url = pickProfilePictureUrl(candidate);
    if (url) return url;
  }

  return '';
}

async function fetchLeadAvatar({ evolutionBaseUrl, evolutionApiKey, evolutionInstance, telefone }) {
  const base = String(evolutionBaseUrl || '').replace(/\/+$/, '');
  const instance = String(evolutionInstance || '').trim();
  const number = String(telefone || '').replace(/\D/g, '');

  if (!base || !evolutionApiKey || !instance || !number) {
    return {
      url: '',
      status: 'not_configured',
      warning: 'evolution_profile_picture_not_configured',
    };
  }

  try {
    const response = await n8nHttpRequest.call(this, {
      method: 'POST',
      url: `${base}/chat/fetchProfilePictureUrl/${encodeURIComponent(instance)}`,
      headers: {
        apikey: evolutionApiKey,
        'Content-Type': 'application/json',
      },
      body: { number },
      json: true,
      timeout: 8000,
    });

    const url = pickProfilePictureUrl(response);
    if (!url) {
      return {
        url: '',
        status: 'not_available',
        warning: 'lead_profile_picture_empty',
      };
    }

    return {
      url,
      status: 'ok',
      warning: null,
    };
  } catch (error) {
    return {
      url: '',
      status: 'error',
      warning: 'lead_profile_picture_fetch_failed',
      error: error?.message || String(error),
    };
  }
}

async function getFirst(args) {
  const result = await supabaseRequest.call(this, args);
  return Array.isArray(result) ? result[0] : result;
}

async function getMany(args) {
  const result = await supabaseRequest.call(this, args);
  return Array.isArray(result) ? result : (result ? [result] : []);
}

function buildRecentMessagesText(messages) {
  return (messages || [])
    .map((m) => {
      const who = m.sender_type === 'agent' || m.direction === 'outbound' ? 'Ju' : 'Cliente';
      return `${who}: ${m.content || ''}`;
    })
    .filter(Boolean)
    .join('\n');
}

function buildOperationalContext({ lead, deal, conversation, recentMessages, currentMessage }) {
  const meta = lead?.metadata || {};

  const collected = {
    objetivo: deal?.intent || meta.objetivo || meta.finalidade || '',
    finalidade: deal?.purpose || meta.finalidade || '',
    bairro_interesse: deal?.location_preference || meta.bairro_interesse || '',
    faixa_valor: [
      deal?.budget_min ? `mín ${deal.budget_min}` : '',
      deal?.budget_max ? `máx ${deal.budget_max}` : '',
    ].filter(Boolean).join(' / ') || meta.faixa_valor || '',
    tipo_imovel: deal?.property_type || meta.tipo_imovel || '',
    timeline: deal?.timeline || meta.timeline || '',
    pagamento: deal?.payment_method || meta.payment_method || '',
  };

  const missing = [];
  if (!collected.objetivo && !collected.finalidade) missing.push('objetivo: morar ou investir');
  if (!collected.bairro_interesse) missing.push('bairro/região de interesse');
  if (!collected.faixa_valor) missing.push('faixa de valor');
  if (!collected.timeline) missing.push('prazo/timeline');

  let ctx = '';
  ctx += '<estado_atual>\n';
  ctx += `tenant_id: ${lead.tenant_id}\n`;
  ctx += `lead_id: ${lead.id}\n`;
  ctx += `deal_id: ${deal?.id || ''}\n`;
  ctx += `conversation_id: ${conversation?.id || ''}\n`;
  ctx += `nome: ${lead.name || 'Cliente'}\n`;
  ctx += `telefone: ${lead.phone || lead.phone_normalized || ''}\n`;
  ctx += `lead_status: ${lead.status || 'new'}\n`;
  ctx += `ai_status: ${lead.ai_status || ''}\n`;
  ctx += `ai_temperature: ${lead.ai_temperature || ''}\n`;
  ctx += `conversation_status: ${conversation?.status || 'open'}\n`;
  ctx += `ai_paused: ${conversation?.ai_paused === true ? 'true' : 'false'}\n`;
  ctx += '</estado_atual>\n\n';

  ctx += '<dados_coletados>\n';
  for (const [key, value] of Object.entries(collected)) {
    ctx += `${key}: ${text(value) || 'não informado'}\n`;
  }
  ctx += '</dados_coletados>\n\n';

  ctx += '<campos_faltantes>\n';
  ctx += missing.length ? missing.map((m) => `- ${m}`).join('\n') : 'nenhum campo crítico faltante';
  ctx += '\n</campos_faltantes>\n\n';

  ctx += '<historico_recente>\n';
  ctx += buildRecentMessagesText(recentMessages) || 'sem histórico recente salvo';
