  if (!/juremabksimoveis\.com\.br\/imoveis\//i.test(url)) return '';
  if (/localhost|127\.0\.0\.1|\s/i.test(url)) return '';
  return url;
}

function stripCodeFence(value) {
  return clean(value)
    .replace(/^\`\`\`(?:json)?\s*/i, '')
    .replace(/\s*\`\`\`$/i, '')
    .trim();
}

function tryParseJson(value) {
  const raw = stripCodeFence(value);
  if (!raw || !/^[\[{]/.test(raw)) return null;
  try {
    return JSON.parse(raw);
  } catch (error) {
    return null;
  }
}

function findCards(value, depth = 0) {
  if (!value || depth > 5) return [];
  if (Array.isArray(value)) {
    if (value.some((item) => item && typeof item === 'object' && (item.url || item.preview || item.operational_features))) {
      return value.filter((item) => item && typeof item === 'object');
    }
    return value.flatMap((item) => findCards(item, depth + 1));
  }
  if (typeof value === 'object') {
    if (Array.isArray(value.cards)) return value.cards;
    if (Array.isArray(value.output?.cards)) return value.output.cards;
    if (Array.isArray(value.data?.cards)) return value.data.cards;
    return Object.values(value).flatMap((item) => findCards(item, depth + 1));
  }
  return [];
}

function cardUrls(cards) {
  const urls = [];
  for (const card of cards) {
    const url = validPropertyUrl(card.url || card.link || card.link_do_imovel);
    if (url && !urls.includes(url)) urls.push(url);
  }
  return urls;
}

function stripLegacyPropertyDump(value) {
  const propertyUrlPattern = /https?:\/\/\S*juremabksimoveis\.com\.br\/imoveis\/\S*/i;

  return clean(value)
    .split(/\r?\n/)
    .map((line) => clean(line))
    .map((line) => {
      const url = line.match(propertyUrlPattern)?.[0] || '';
      if (url && line !== url) return url;
      return line;
    })
    .filter((line) => {
      if (!line) return true;
      if (/^separei esta opcao pra voce:/i.test(norm(line))) return false;
      if (/^(apartamento|casa|flat|cobertura|terreno|sala)\s+em\s+[\w\s-]{2,80}$/i.test(norm(line))) return false;
      if (/^(apartamento|casa|flat|cobertura|terreno|sala)\s+para\s+(venda|aluguel)\s+(no|na|em)\s+[\w\s-]{2,100}$/i.test(norm(line))) return false;
      if (/(m2|m²|quartos?|suites?|vagas?|r\$|\|\s*)/i.test(line) && !validPropertyUrl(line)) return false;
      return true;
    })
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizeTextOutput(value) {
  const text = clean(value);
  if (!text) return '';

  const parsed = tryParseJson(text);
  const cards = findCards(parsed);
  if (cards.length) {
    const urls = cardUrls(cards).slice(0, 3);
    if (urls.length) return urls.join('\n\n');
    return clean(parsed?.fallback_message || parsed?.warning || '');
  }

  return text
    .replace(/^[ \t]*[-*]\s+/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const output = stripLegacyPropertyDump(normalizeTextOutput($json.output));

return [{
  json: {
    ...$json,
    output,
    presentation_governed: true,
    presentation_policy: 'post_card_contextual_guidance_v1',
  },
}];

function clean(value) {
  return String(value ?? '').trim();
}

function norm(value) {
  return clean(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function validUrl(value) {
  const text = clean(value);
  return /^https?:\/\/\S+$/i.test(text);
}

function stripMarkdown(value) {
  return clean(value)
    .replace(/\`\`\`[\s\S]*?\`\`\`/g, '')
    .replace(/\`([^\`]+)\`/g, '$1')
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    .replace(/~~([^~]+)~~/g, '$1')
    .replace(/^[ \t]{0,3}#{1,6}[ \t]+/gm, '')
    .replace(/[ \t]*👉[ \t]*/g, '')
    .replace(/[ \t]{2,}/g, ' ');
}

function humanJoin(parts) {
  const items = parts.map(clean).filter(Boolean);
  if (items.length <= 1) return items[0] || '';
  if (items.length === 2) return items.join(' e ');
  return items.slice(0, -1).join(', ') + ' e ' + items[items.length - 1];
}

function collapseListBlocks(value) {
  const lines = stripMarkdown(value).split(/\r?\n/);
  const out = [];
  let pendingIntro = '';
  let bullets = [];

  function flush() {
    if (!bullets.length) {
      if (pendingIntro) out.push(pendingIntro);
      pendingIntro = '';
      return;
    }

    const joined = humanJoin(bullets);
    if (pendingIntro) {
      const separator = /[:?]$/.test(pendingIntro) ? ' ' : '. ';
      out.push(pendingIntro.replace(/[?]$/, ':') + separator + joined + '.');
    } else {
      out.push(joined + '.');
    }
    pendingIntro = '';
    bullets = [];
  }

  for (const rawLine of lines) {
    const line = clean(rawLine);
    if (!line) {
      if (pendingIntro && !bullets.length) continue;
      flush();
      if (out[out.length - 1] !== '') out.push('');
      continue;
    }

    if (validUrl(line)) {
      flush();
      out.push(line);
      continue;
    }

    const bullet = line.match(/^(?:[-*•]+|\d+[.)]|[a-z][.)])\s+(.+)$/i);
    if (bullet) {
      bullets.push(bullet[1].replace(/[.;]+$/, ''));
      continue;
    }

    if (bullets.length) flush();
    if (line.endsWith(':') && !pendingIntro) {
      pendingIntro = line;
      continue;
    }

    if (pendingIntro) flush();
    out.push(line);
  }

  flush();
  return out
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function removeArtificialOpeners(value) {
  return clean(value)
    .replace(/^(claro|com certeza|perfeito|ótimo|otimo|legal)[!.]?\s+/i, '')
    .replace(/^entendi[!.]?\s+entendi[!.]?\s+/i, 'Entendi. ');
}

function contextText() {
  const parts = [
    $json._context,
    $json.mensagemCliente,
    $json.deal?.property_type,
    $json.deal?.location_preference,
    $json.deal?.intent,
    $json.lead?.metadata?.tipo_imovel,
    $json.lead?.metadata?.bairro_interesse,
    ($json.recent_messages || []).map((m) => m.content).join(' '),
  ];
  return norm(parts.filter(Boolean).join(' '));
}

function redundantPropertyTypeQuestion(sentence, ctx) {
  const text = norm(sentence);
  const asksType = /voce procura|esta procurando|busca|quer/.test(text) && /apartamento|apto|casa|tipo de imovel|tipologia/.test(text);
  if (!asksType) return false;
  return /\bcasa\b|\bapartamento\b|\bapto\b|\bflat\b|\bterreno\b|\bsala\b/.test(ctx);
}

function blockedQuestion(sentence) {
  const blocked = Array.isArray($json.blocked_questions) ? $json.blocked_questions.map(norm).filter(Boolean) : [];
  if (!blocked.length || !sentence.includes('?')) return false;
  const text = norm(sentence);
  return blocked.some((question) => question && (text.includes(question) || question.includes(text.replace(/\?$/, ''))));
}

function removeRedundantQuestions(value) {
  const ctx = contextText();
  const chunks = clean(value).match(/[^.!?\n]+[.!?]?|\n+/g) || [value];
  return chunks
    .filter((chunk) => {
      const sentence = clean(chunk);
      if (!sentence || /^\n+$/.test(chunk)) return true;
      if (redundantPropertyTypeQuestion(sentence, ctx)) return false;
      if (blockedQuestion(sentence)) return false;
      return true;
    })
    .join('')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function softenChatbotPhrases(value) {
  return clean(value)
    .replace(/\bpara que eu possa\b/gi, 'pra eu')
    .replace(/\bgostaria de saber\b/gi, 'me conta')
    .replace(/\bpor favor[, ]*/gi, '')
    .replace(/\bsegue(m)? (abaixo )?(as )?(opcoes|opções|informacoes|informações)\b/gi, 'separei')
    .replace(/\bqual opção\b/gi, 'qual delas')
    .replace(/\bqual opcao\b/gi, 'qual delas')
    .replace(/\bopções\b/g, 'opcoes')
    .replace(/\binformações\b/g, 'informacoes')
    .replace(/\bimóvel\b/g, 'imovel')
    .replace(/\bimóveis\b/g, 'imoveis');
}

function normalizeWhitespace(value) {
  const text = clean(value)
    .split(/\n/)
    .map((line) => clean(line))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/([.!?]){2,}/g, '$1')
    .replace(/^separei:\s*/i, 'Separei ')
    .trim();
  return text.charAt(0).toLowerCase() === text.charAt(0)
    ? text.charAt(0).toUpperCase() + text.slice(1)
    : text;
}

function govern(value) {
  let text = clean(value);
  if (!text) return '';
  text = stripMarkdown(text);
  text = collapseListBlocks(text);
  text = removeArtificialOpeners(text);
  text = removeRedundantQuestions(text);
  text = softenChatbotPhrases(text);
  text = normalizeWhitespace(text);
  return text;
}

const output = govern($json.output);

return [{
  json: {
    ...$json,
    output,
    conversational_style_governed: true,
  },
}];

function clean(value) {
  return String(value ?? '').trim();
}

function firstText(...values) {
  return values.map(clean).find(Boolean) || '';
}

function normalizeBaseUrl(value) {
  return clean(value).replace(/\/+$/, '');
}

async function httpRequest(options) {
  if (this.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  if (this.helpers?.request) return await this.helpers.request(options);
  throw new Error('HTTP helper indisponivel para persistir transcript de audio');
}

async function patchInboundTranscript({ baseUrl, apiKey, conversationId, externalMessageId, transcript }) {
  if (!baseUrl || !apiKey || !conversationId || !externalMessageId || !transcript) return null;

  return await httpRequest.call(this, {
    method: 'PATCH',
    url: normalizeBaseUrl(baseUrl) + '/rest/v1/conversation_messages',
    qs: {
      conversation_id: 'eq.' + conversationId,
      external_message_id: 'eq.' + externalMessageId,
      direction: 'eq.inbound',
    },
    headers: {
      apikey: apiKey,
      Authorization: 'Bearer ' + apiKey,
      'Content-Type': 'application/json',
      Prefer: 'return=minimal',
    },
    body: {
      content: transcript,
      message_type: 'audio',
    },
    json: true,
    timeout: 30000,
  });
}

const items = $input.all();
const output = [];

for (const item of items) {
  const source = item.json || {};
  const base = $('Code in JavaScript').first().json || {};
  const config = $('dados do banco').first().json || {};
  const transcript = firstText(
    source.text,
    source.transcription,
    source.transcript,
    source.audioText
  );
  const fallbackAudioText = '[audio recebido, mas a transcricao falhou temporariamente]';
  const inboundText = transcript || fallbackAudioText;

  const enriched = {
    ...base,
    ...source,
    audioText: inboundText,
    transcript,
    mensagemCliente: inboundText,
    normalized_inbound_message: inboundText,
    messageType: 'audio',
    audio_operational_policy: 'audio_as_normal_inbound_message_v1',
    audio_transcript_persisted: false,
  };

  if (!transcript) {
    output.push({
      json: {
        ...enriched,
        audio_transcript_warning: 'empty_transcript',
      },
      binary: item.binary,
    });
    continue;
  }

  try {
    await patchInboundTranscript.call(this, {
      baseUrl: firstText(config.URL_SUPABASE, base.URL_SUPABASE, $vars.SUPABASE_URL),
      apiKey: firstText(config.SUPABASE_SERVICE_ROLE_KEY, base.SUPABASE_SERVICE_ROLE_KEY, $vars.SUPABASE_SERVICE_ROLE_KEY),
      conversationId: base.conversation?.id || base.conversation_id,
      externalMessageId: base.external_message_id,
      transcript,
    });

    output.push({
      json: {
        ...enriched,
        audio_transcript_persisted: true,
      },
      binary: item.binary,
    });
  } catch (error) {
    output.push({
      json: {
        ...enriched,
        audio_transcript_persisted: false,
        audio_transcript_warning: error?.message || String(error),
      },
      binary: item.binary,
    });
  }
}

return output;

function clean(value) {
  return String(value ?? '').trim();
}

function validPropertyUrl(value) {
  const url = clean(value);

  if (!/^https?:\/\/\S+$/i.test(url)) {
    return false;
  }

  if (
    !/juremabksimoveis\.com\.br\/imoveis\//i.test(url)
  ) {
    return false;
  }

  if (
    /localhost|127\.0\.0\.1|\s/i.test(url)
  ) {
    return false;
  }

  return true;
}

function stripLegacyPropertyDump(text) {

  const lines = clean(text)
    .split(/\r?\n/)
    .map(v => clean(v));

  const cleaned = [];

  for (const line of lines) {

    if (!line) continue;

    const normalized = line
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase();

    // remove template SDR legado
    if (
      normalized.includes(
        'separei esta opcao pra voce'
      )
    ) {
      continue;
    }

    // remove linhas SEO dump MUITO específicas
    if (
      /^(apartamento|casa|flat|cobertura|terreno|sala)\s+para\s+(venda|aluguel)\s+(no|na|em)\s+/i
        .test(line)
    ) {
      continue;
    }

    // remove linha técnica imobiliária
    if (
      /(m²|m2|quartos?|su[ií]tes?|vagas?|r\$)/i
        .test(line)
      &&
      !validPropertyUrl(line)
    ) {
      continue;
    }

    cleaned.push(line);
  }

  return cleaned
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function preserveContextAndUrl(text) {

  const lines = clean(text)
    .split('\n')
    .map(v => clean(v))
    .filter(Boolean);

  const blocks = [];

  let buffer = [];

  function isUrl(value) {
    return /^https?:\/\//i.test(value);
  }

  for (const line of lines) {

    buffer.push(line);

    if (isUrl(line)) {

      blocks.push(
        buffer.join('\n')
      );

      buffer = [];
    }
  }

  if (buffer.length) {
    blocks.push(
      buffer.join('\n')
    );
  }

  return blocks.join('\n\n');
}

const original =
  clean($json.output);

const sanitized =
  stripLegacyPropertyDump(
    original
  );

const output =
  preserveContextAndUrl(
    sanitized
  );

return [
  {
    json: {
      ...$json,

      output,

      presentation_governed: true,

      presentation_policy:
        'native_preview_safe_v2'
    }
  }
];
